{
  "story": "Magma chambers fill, pressure builds, gases expand, and magma finally breaches the surface.",
  "aha": {
    "stateId": "erupt",
    "observation": "Expanding gas bubbles drive the explosive eruption when pressure exceeds containment."
  },
  "layout": {
    "preset": "stepper-card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "pic",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.stepIndex",
        "regions": "variant.regions",
        "values": "state.active"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "values": "state.why"
      }
    },
    {
      "id": "readouts",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Eruption Step",
      "options": ["chamber", "pressure", "erupt"]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Volcano Eruption Stages",
        "regions": [
          {
            "id": "chamber",
            "label": "Magma Chamber",
            "kind": "reservoir",
            "values": ["Molten rock accumulates underground"]
          },
          {
            "id": "conduit",
            "label": "Conduit",
            "kind": "pathway",
            "values": ["Gases dissolve under intense heat"]
          },
          {
            "id": "crater",
            "label": "Summit Crater",
            "kind": "vent",
            "values": ["Ash and lava burst forth"]
          }
        ],
        "states": [
          {
            "id": "chamber",
            "label": "Accumulation",
            "short": "Fill",
            "sentence": "Magma pools in the deep chamber.",
            "why": "Deep storage fills over time.",
            "active": ["chamber"],
            "calloutRegion": "chamber",
            "readouts": [
              {
                "id": "p1",
                "label": "Pressure",
                "value": "Low"
              }
            ]
          },
          {
            "id": "pressure",
            "label": "Compression",
            "short": "Build",
            "sentence": "Dissolved gases expand as magma rises.",
            "why": "Pressure mounts inside the conduit.",
            "active": ["conduit"],
            "calloutRegion": "conduit",
            "readouts": [
              {
                "id": "p2",
                "label": "Pressure",
                "value": "High"
              }
            ]
          },
          {
            "id": "erupt",
            "label": "Eruption",
            "short": "Burst",
            "sentence": "The vent shatters and lava erupts.",
            "why": "Gas breakout powers the blast.",
            "active": ["crater"],
            "calloutRegion": "crater",
            "readouts": [
              {
                "id": "p3",
                "label": "Pressure",
                "value": "Released"
              }
            ]
          }
        ]
      }
    ]
  }
}
